HELP_TEXT = None
DOC_TEXT = None
ERRORLIST_TEXT = None
VERSION_TEXT = None

def load_embeds():
    global HELP_TEXT, DOC_TEXT, ERRORLIST_TEXT, VERSION_TEXT
    # Try embedded first, else load from /tmp for dev
    if HELP_TEXT is None:
        try:
            with open("/tmp/embed_help.bin","rb") as f:
                HELP_TEXT = f.read().decode('utf-8', errors='surrogateescape')
        except: HELP_TEXT = ""
    if DOC_TEXT is None:
        try:
            with open("/tmp/embed_doc.bin","rb") as f:
                DOC_TEXT = f.read().decode('utf-8', errors='surrogateescape')
        except: DOC_TEXT = ""
    if ERRORLIST_TEXT is None:
        try:
            with open("/tmp/embed_errorlist.bin","rb") as f:
                ERRORLIST_TEXT = f.read().decode('utf-8', errors='surrogateescape')
        except: ERRORLIST_TEXT = ""
    if VERSION_TEXT is None:
        try:
            with open("/tmp/embed_version.bin","rb") as f:
                VERSION_TEXT = f.read().decode('utf-8', errors='surrogateescape')
        except: VERSION_TEXT = "Cppcheck 2.19 dev\n"

VALID_ENABLE = {"warning","performance","portability","information","style","unusedFunction","missingInclude","all"}
VALID_CHECK_LEVEL = {"reduced","normal","exhaustive"}
VALID_OUTPUT_FORMAT = {"text","sarif","xml","xmlv2","xmlv3"}
VALID_PLATFORMS = {"unix32","unix64","win32A","win32W","win64","native","unspecified"}
VALID_REPORT = {"normal","autosar","cert-c-2016","cert-cpp-2016","misra-c-2012","misra-c-2023","misra-c-2025","misra-cpp-2008","misra-cpp-2023"}
