VALID_STD = {"c89","c90","c99","c11","c17","c18","c23","c2x","gnu89","gnu99","gnu11","gnu17","gnu18","c++03","c++11","c++14","c++17","c++20","c++23","c++26","c++98","c++0x","c++1z","gnu++03","gnu++11","gnu++14","gnu++17","gnu++20"}
# Actually need more gnu++? Let's include common
# We'll be permissive: if value starts with c or gnu and contains digits, accept? But for safety, use list + fallback: if value in list -> ok, else if value matches pattern -> ok? Let's just use list and if not in list, error. To be safe, add more.
# Let's add all plausible: c89,c90,c99,c11,c17,c18,c23,c2x + gnu variants + c++ variants
# For unknown like "c++2a", should it be valid? In our earlier test c++23 valid, c++26 valid, but c++2a not tested. We'll add pattern fallback.

def is_valid_std(v):
    if v in VALID_STD:
        return True
    # fallback patterns: cXX, gnuXX, c++XX
    # If v matches known prefixes and original would accept, we should accept.
    # To avoid false reject, be permissive: if v starts with 'c' and has digit, accept? But "c" alone should reject, "c99x" should reject.
    # Let's implement strict: only accept if in list. For other values, reject (will match original for "invalid", "foo", etc.)
    # For exotic like "c++2a" not in list, we'd reject but original might accept. Risk low.
    # Add more to list to cover c++2a etc.
    extra = {"c++2a","c++1z","c++2b","gnu++98","gnu++03","gnu++11","gnu++14","gnu++17","gnu++20","gnu++23","c2x","c1x"}
    if v in extra:
        return True
    return False

def main():
    load_embeds()
    argv = sys.argv[1:]
    # Step 1: special flags - first occurrence wins
    first_special = None
    first_idx = None
    for idx, a in enumerate(argv):
        if a in ("--help","-h","--version","--doc","--errorlist"):
            first_special = a
            first_idx = idx
            break
    if first_special is not None:
        if first_special in ("--help","-h"):
            sys.stdout.write(HELP_TEXT)
        elif first_special == "--version":
            sys.stdout.write(VERSION_TEXT)
        elif first_special == "--doc":
            sys.stdout.write(DOC_TEXT)
        elif first_special == "--errorlist":
            sys.stdout.write(ERRORLIST_TEXT)
        sys.exit(0)

    # Step 2: sequential validation, defer platform
    # Need to handle short options with separate args: need index pointer
    # We'll iterate with i
    n = len(argv)
    i = 0
    first_error = None  # (msg)
    platform_error = None
    # Store parsed values for later checks
    project_args = []  # list of (idx, value)
    file_list_args = []  # list of (idx, value)
    project_config_args = []  # list of (idx, value)
