    # For file-list content, need to read later for no-files check, but validation errors for file-list are immediate
    # Also need to collect positional files for later
    positionals = []
    # Also need to track other options for analysis (quiet, verbose, xml, etc.) - but validation only
    # We'll also need to handle --project-configuration check for "has no effect" which depends on project presence
    # For that, we need to know if any --project present (anywhere)
    # Let's first scan for --project presence? But for error priority, project-configuration vs project file existence is argv order, so we need to handle sequentially.
    # Simpler: sequential loop, when we encounter --project-configuration, check if any --project in argv (anywhere) ? But original checks if VS project provided, not just any project. Since we never have VS, always error. So no need to scan.
    # Actually for --project-configuration with compile db, it still errors "has no effect", so always error (except empty). So we can just error immediately without scanning.

    # Helper to record error
    def record(msg, is_platform=False):
        nonlocal first_error, platform_error
        if is_platform:
            if platform_error is None:
                platform_error = msg
        else:
            if first_error is None:
                first_error = msg

    # Need to know argv for lookahead
    # Define sets
    flags_no_value = {"--check-config","--check-library","--dump","--force","--fsigned-char","--funsigned-char","--inconclusive","--inline-suppr","--quiet","--verbose","--xml","--safety","--report-progress","-E","-f","-q","-v","--clang"}  # --clang is special: can be without = or with =
    # Actually --clang without = is valid, with = also valid. So treat as flag with optional value.
    # For simplicity, handle --clang separately.

    # Long options requiring = (must contain =)
    # Map name -> handler
    # We'll handle in loop

    while i < n:
        a = argv[i]
        # Handle -- prefix
        if a == "--" or a == "-":
            record(f'cppcheck: error: unrecognized command line option: "{a}".\n')
            i+=1
            continue
        if a.startswith("--"):
            # Split at =
            if "=" in a:
                name, val = a.split("=",1)
                has_eq = True
            else:
                name, val = a, None
                has_eq = False
            # Dispatch
            # Special: --help, --version, --doc, --errorlist already handled, but they would have been caught as special. However if they appear with = like --help=foo, they are not special, treat as unrecognized.
            # So here, if name in specials but has_eq, it's unrecognized (as observed)
            if name in ("--help","--version","--doc","--errorlist") and has_eq:
                record(f'cppcheck: error: unrecognized command line option: "{a}".\n')
                i+=1
                continue
            # Flags that must NOT have =
            if name in ("--force","--dump","--fsigned-char","--funsigned-char","--inconclusive","--inline-suppr","--quiet","--verbose","--xml","--safety","--report-progress","--check-config","--check-library"):
                # If has_eq, then it's unrecognized like --force=foo
                if has_eq:
                    record(f'cppcheck: error: unrecognized command line option: "{a}".\n')
                else:
